# Chain Lightning: a bolt that leaps between up to three enemies, weakening each jump.

DAMAGES = [5, 3, 2]
JUMP_RADIUS = 3


def on_cast(ctx, caster, target):
    me = ctx.entity(caster)
    if me is None:
        return
    victim = ctx.entity_at(target)
    if victim is None:
        ctx.log("The lightning crackles into empty air.")
        return

    # Snapshot of legal chain candidates taken before anything is damaged, so
    # creatures spawned mid-cast cannot be struck.
    candidates = []
    for other in ctx.entities():
        if other.faction != me.faction and other.id != caster:
            candidates.append(other.id)

    hit = set()
    current = victim.id
    pos = victim.pos
    links = 0

    for amount in DAMAGES:
        if current is None:
            break
        hit.add(current)
        ctx.damage(current, amount, source=caster)
        links += 1
        here = ctx.entity(current)
        if here is not None:
            pos = here.pos
        current = pick_next(ctx, pos, candidates, hit)

    if links == 1:
        ctx.log("The lightning finds nowhere to leap.")
    else:
        ctx.log(f"The lightning arcs through {links} creatures!")


def pick_next(ctx, pos, candidates, hit):
    best = None
    best_dist = None
    for cid in candidates:
        if cid in hit:
            continue
        other = ctx.entity(cid)
        if other is None:
            continue
        dist = pos.distance_to(other.pos)
        if dist > JUMP_RADIUS:
            continue
        if not ctx.has_line_of_sight(pos, other.pos):
            continue
        if best_dist is None or dist < best_dist:
            best_dist = dist
            best = [cid]
        elif dist == best_dist:
            best.append(cid)
    if best is None:
        return None
    if len(best) == 1:
        return best[0]
    return ctx.choice(best)


define_spell(
    id="chain_lightning",
    name="Chain Lightning",
    description="A bolt strikes a target for 5 damage, then leaps to the nearest enemy within 3 tiles for 3 damage, then once more for 2. Each enemy is struck only once.",
    mana_cost=4,
    cooldown=3,
    target="entity",
    range=6,
    on_cast=on_cast,
)

# Chain Lightning: hits an enemy for 5, then arcs to two more nearby foes for 3 and 1.

DAMAGES = [5, 3, 1]
JUMP_RADIUS = 3


def find_next(ctx, ctx_pos, caster_faction, hit_ids):
    best = None
    best_dist = None
    for other in ctx.entities_in_radius(ctx_pos, JUMP_RADIUS):
        if other.faction == caster_faction:
            continue
        if other.id in hit_ids:
            continue
        if not ctx.has_line_of_sight(ctx_pos, other.pos):
            continue
        dist = ctx_pos.distance_to(other.pos)
        if best_dist is None or dist < best_dist:
            best = other
            best_dist = dist
    return best


def on_cast(ctx, caster, target):
    me = ctx.entity(caster)
    if me is None:
        return
    victim = ctx.entity_at(target)
    if victim is None or victim.faction == me.faction:
        ctx.log("The lightning crackles and fades with no foe to strike.")
        return

    hit_ids = set()
    current = victim
    for index, amount in enumerate(DAMAGES):
        if current is None:
            ctx.log("The lightning finds nothing more to leap to.")
            return
        pos = current.pos
        hit_ids.add(current.id)
        if index == 0:
            ctx.log(f"Lightning strikes the {current.name}!")
        else:
            ctx.log(f"The bolt arcs to the {current.name}!")
        ctx.damage(current.id, amount, source=caster)
        if index + 1 < len(DAMAGES):
            current = find_next(ctx, pos, me.faction, hit_ids)
        else:
            current = None


define_spell(
    id="chain_lightning",
    name="Chain Lightning",
    description="Send a bolt of lightning at an enemy that arcs to two more nearby foes, weakening with each jump (5, then 3, then 1 damage).",
    mana_cost=5,
    cooldown=3,
    target="entity",
    range=6,
    on_cast=on_cast,
)
